"proposal": {
  "capability": "deployment.set-probes",
  "target": {
    "group": "apps",
    "kind": "Deployment",
    "namespace": "payments",
    "name": "payments-worker",
    "uid": "uid-deployment-payments-worker"
  },
  "params": {
    "container": "app",
    "liveness": {
      "timeoutSeconds": 5
    }
  },
  "expected_effect": "Increase liveness probe timeout to 5s to allow new version sufficient time to start before probe fails",
  "rationale": "The new version (2.11.1) shows startup delays (46s before kill) and probe timeout (1s) is too short. Logs show probe took 2300ms (2.3s) to respond. Increasing timeout to 5s would allow the app to respond before probe fails, while keeping other probe parameters unchanged. The application bug (invalid currency code) is a separate issue that would require code changes not allowed here.",
  "cited_evidence_ids": ["ev-rollout_history", "ev-target_events", "ev-pod_states", "ev-container_logs_tail"],
  "cited_predicates": ["probe_kills", "killed_during_startup", "rollout_changed_the_app"]
}
